// ---- Config: put your allowed Telegram user IDs here ----
const ALLOW_LIST = new Set([
  YOUR_TELEGRAM_CHAT_ID,   // you
  YOUR_TELEGRAM_CHAT_ID
  // 123456789,  // tester 1
  // 987654321,  // tester 2
]);

// Helper: extract chatID/fromID from various Telegram update types
function extractIds(update = {}) {
  const msg =
    update.message ||
    update.edited_message ||
    update.channel_post ||
    update.edited_channel_post ||
    (update.callback_query && update.callback_query.message) ||
    null;

  const fromObj =
    update.from ||
    (update.callback_query && update.callback_query.from) ||
    (msg && msg.from) ||
    null;

  const chatObj = (msg && msg.chat) || null;

  const fromID = fromObj?.id ?? null;
  const chatID = chatObj?.id ?? null;

  return { fromID, chatID };
}

// Map each incoming item to include flags + safe fields
const out = $input.all().map(item => {
  const j = item.json || {};
  const { fromID, chatID } = extractIds(j);
  const authorized = fromID != null && ALLOW_LIST.has(Number(fromID));

  // ✅ Output BOTH casings for backward compatibility
  item.json.fromID = fromID;
  item.json.fromId = fromID;  // lowercase for old nodes
  item.json.chatID = chatID;
  item.json.chatId = chatID;  // lowercase for old nodes
  item.json.authorized = authorized;

  // ✅ Add a unique traceId for this run
  item.json.traceId =
    'trace-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8);

  // Optional: prebuild a polite reply for unknown users
  if (!authorized && chatID != null) {
    item.json.reply = {
      method: "sendMessage",
      chat_id: chatID,
      text:
        "🚧 Bot is currently in demo mode. Access is restricted.\n\n" +
        "If you think this is a mistake, DM the owner to be whitelisted."
    };
  }

  // Optional: marker for analytics/filters
  if (!authorized) item.json.unauthorized = true;

  return item;
});

return out;
